<section class="panel image-detail"><div><?php if($product['image_id']): ?><img class="preview" src="<?= e(url('media',['id'=>$product['image_id'],'size'=>'large'])) ?>" alt="<?= e($product['title']) ?>"><?php else: ?><div class="product-placeholder">نامیرا</div><?php endif ?></div><div><h1><?= e($product['title']) ?></h1><p class="prose"><?= e($product['description']) ?></p><form method="post"><?= Namira\Security::field() ?><input type="hidden" name="action" value="cart"><div class="field"><label for="variant">انتخاب تنوع</label><select id="variant" name="variant_id"><?php foreach($variants as $v): ?><option value="<?= $v['id'] ?>" <?= $v['stock']<1?'disabled':'' ?>><?= e($v['attributes']) ?> · <?= fa(number_format((int)($v['sale_price']??$v['price']))) ?> تومان · موجودی <?= fa($v['stock']) ?></option><?php endforeach ?></select></div><div class="field"><label for="quantity">تعداد</label><input id="quantity" type="number" name="quantity" min="1" max="99" value="1" required></div><button class="primary">افزودن به سبد خرید</button></form></div></section>
